int contains(tnode *t, int v) {
    if (t == NULL)
        return 0;
    if (v == t->value)
        return 1;
    if (v < t->value)
        return contains(t->left, v);
    return contains(t->right, v);
}

tnode *insert(tnode *t, int v) {
    if (t == NULL)
        return new_node(v);
    if (v < t->value)
        t->left = insert(t->left, v);
    else if (v > t->value)
        t->right = insert(t->right, v);
    return t;
}
